describe('JavaScript Error Recovery', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display error boundary UI when JavaScript error occurs', () => {
    cy.window().then((win) => {
      cy.stub(win.console, 'error');
    });

    cy.get('[data-testid="trigger-error-btn"]').click();

    cy.get('[data-testid="error-boundary"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');
    cy.get('[data-testid="error-details"]').should('be.visible');
  });

  it('should allow user to recover from error state by clicking reset button', () => {
    cy.get('[data-testid="trigger-error-btn"]').click();

    cy.get('[data-testid="error-boundary"]').should('be.visible');

    cy.get('[data-testid="reset-error-btn"]').click();

    cy.get('[data-testid="error-boundary"]').should('not.exist');
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should maintain app functionality after error recovery', () => {
    cy.get('[data-testid="trigger-error-btn"]').click();
    cy.get('[data-testid="reset-error-btn"]').click();

    cy.get('[data-testid="input-field"]').type('test input');
    cy.get('[data-testid="submit-btn"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should handle multiple consecutive errors gracefully', () => {
    cy.get('[data-testid="trigger-error-btn"]').click();
    cy.get('[data-testid="error-boundary"]').should('be.visible');

    cy.get('[data-testid="reset-error-btn"]').click();
    cy.get('[data-testid="error-boundary"]').should('not.exist');

    cy.get('[data-testid="trigger-error-btn"]').click();
    cy.get('[data-testid="error-boundary"]').should('be.visible');

    cy.get('[data-testid="reset-error-btn"]').click();
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should log error information for debugging when error occurs', () => {
    cy.window().then((win) => {
      cy.stub(win.console, 'error').as('consoleError');
    });

    cy.get('[data-testid="trigger-error-btn"]').click();

    cy.get('@consoleError').should('have.been.called');
    cy.get('[data-testid="error-boundary"]').should('be.visible');
  });
});
